using Microsoft.EntityFrameworkCore;
using SemBroncaAI.Garage.Application.Abstractions.Security;
using SemBroncaAI.Garage.Application.Features.SiteManagement;
using SemBroncaAI.Garage.Domain.Common;
using SemBroncaAI.Garage.Domain.Entities.SiteManagement;
using SemBroncaAI.Garage.Infrastructure.Persistence;

namespace SemBroncaAI.Garage.Infrastructure.Services;

public sealed class ManagedSiteAdministration(GarageDbContext db, ICurrentUser currentUser) : IManagedSiteAdministration
{
    public async Task<ManagedSiteDashboard> DashboardAsync(ManagedSiteFilter filter,CancellationToken token)
    {
        var query=db.ManagedSites.AsNoTracking().Include(x=>x.Costs).AsQueryable();
        if(!string.IsNullOrWhiteSpace(filter.Search)){var term=$"%{filter.Search.Trim()}%";query=query.Where(x=>EF.Functions.ILike(x.TradeName,term)||EF.Functions.ILike(x.Domain,term));}
        if(filter.Status is{} status)query=query.Where(x=>x.Status==status); if(filter.FinancialStatus is{} financial)query=query.Where(x=>x.FinancialStatus==financial); if(filter.Active is{} active)query=query.Where(x=>x.Active==active); if(!string.IsNullOrWhiteSpace(filter.Hosting))query=query.Where(x=>x.HostingProvider==filter.Hosting);
        var sites=await query.OrderBy(x=>x.TradeName).ToListAsync(token);var today=DateOnly.FromDateTime(DateTime.UtcNow);var soon=today.AddDays(30);
        var items=sites.Select(x=>new ManagedSiteListItem(x.Id,x.TradeName,x.Domain,x.Status,x.HostingProvider,x.MonthlyFee,RecurringCost(x),NextDue(x),x.FinancialStatus,x.Active)).ToArray();
        return new(sites.Count(x=>x.Active),sites.Count(x=>x.Active&&x.Status is ManagedSiteStatus.Planning or ManagedSiteStatus.InDevelopment or ManagedSiteStatus.Adjustments),sites.Where(x=>x.Active).Sum(x=>x.MonthlyFee),sites.Where(x=>x.Active).Sum(RecurringCost),sites.Where(x=>x.Active).Sum(x=>x.MonthlyFee-RecurringCost(x)),sites.Count(IsPending),sites.Count(x=>Renewals(x).Any(d=>d>=today&&d<=soon)),items);
    }

    public async Task<ManagedSiteDetails?> GetAsync(Guid id,CancellationToken token){var x=await db.ManagedSites.AsNoTracking().Include(x=>x.Mailboxes).Include(x=>x.Costs).Include(x=>x.SupportEntries).Include(x=>x.History).SingleOrDefaultAsync(x=>x.Id==id,token);return x is null?null:Map(x);}

    public async Task<Guid> CreateAsync(ManagedSiteSaveCommand command,CancellationToken token){Validate(command);var now=DateTime.UtcNow;var x=new ManagedSiteEntity(command.TradeName,command.ProjectName,NormalizeDomain(command.Domain),now);Apply(x,command,now);x.History.Add(new(x.Id,"Cadastro criado.",currentUser.UserId,now));db.ManagedSites.Add(x);await db.SaveChangesAsync(token);return x.Id;}
    public async Task<bool> UpdateAsync(Guid id,ManagedSiteSaveCommand command,CancellationToken token){Validate(command);var x=await db.ManagedSites.Include(x=>x.Mailboxes).Include(x=>x.Costs).Include(x=>x.SupportEntries).SingleOrDefaultAsync(x=>x.Id==id,token);if(x is null)return false;Apply(x,command,DateTime.UtcNow);await db.SaveChangesAsync(token);return true;}
    public async Task<bool> SetActiveAsync(Guid id,bool active,CancellationToken token){var now=DateTime.UtcNow;var changed=await db.ManagedSites.Where(x=>x.Id==id).ExecuteUpdateAsync(update=>update.SetProperty(x=>x.Active,active).SetProperty(x=>x.UpdatedAt,now),token);if(changed==0)return false;db.ManagedSiteHistory.Add(new(id,active?"Cadastro reativado.":"Cadastro arquivado.",currentUser.UserId,now));await db.SaveChangesAsync(token);return true;}
    public async Task<bool> AddHistoryAsync(Guid id,string text,CancellationToken token){if(string.IsNullOrWhiteSpace(text)||text.Trim().Length>2000)throw new ArgumentException("Informe uma anotação válida.");if(!await db.ManagedSites.AnyAsync(x=>x.Id==id,token))return false;db.ManagedSiteHistory.Add(new(id,text,currentUser.UserId,DateTime.UtcNow));await db.SaveChangesAsync(token);return true;}

    private static void Validate(ManagedSiteSaveCommand c){var errors=new List<string>();if(string.IsNullOrWhiteSpace(c.TradeName))errors.Add("Nome fantasia é obrigatório.");if(string.IsNullOrWhiteSpace(c.ProjectName))errors.Add("Nome do projeto é obrigatório.");if(string.IsNullOrWhiteSpace(c.Domain))errors.Add("Domínio é obrigatório.");if(!string.IsNullOrWhiteSpace(c.Document)&&!BrazilianDocument.IsValid(c.Document))errors.Add("CPF/CNPJ inválido.");if(c.ContractedRevisions<0||c.UsedRevisions<0||c.EmailIncludedCount<0||c.DevelopmentContractValue<0||c.DevelopmentReceivedValue<0||c.MonthlyFee<0||c.EstimatedRecurringCost<0||c.MonthlySupportHours<0||c.DomainCost<0||c.HostingCost<0||c.EmailCost<0||c.DueDay is <0 or >31||c.Costs.Any(x=>x.Value<0)||c.SupportEntries.Any(x=>x.HoursSpent<0||x.AdditionalValue<0))errors.Add("Valores numéricos não podem ser negativos.");if(c.UsedRevisions>c.ContractedRevisions&&c.ContractedRevisions>0)errors.Add("Revisões utilizadas excedem as contratadas.");if(c.Mailboxes.Any(x=>string.IsNullOrWhiteSpace(x.Address)||!x.Address.Contains('@')))errors.Add("Existe uma caixa de e-mail inválida.");if(errors.Count>0)throw new ArgumentException(string.Join(" ",errors));}
    private static string NormalizeDomain(string value){var domain=value.Trim().ToLowerInvariant();if(Uri.TryCreate(domain,UriKind.Absolute,out var uri))domain=uri.Host;return domain.TrimEnd('/');}
    private static decimal Monthly(decimal value,ManagedSitePeriodicity p)=>p switch{ManagedSitePeriodicity.Monthly=>value,ManagedSitePeriodicity.Quarterly=>value/3m,ManagedSitePeriodicity.Semiannual=>value/6m,ManagedSitePeriodicity.Annual=>value/12m,_=>0m};
    private static decimal RecurringCost(ManagedSiteEntity x)=>x.EstimatedRecurringCost+Monthly(x.HostingCost,x.HostingPeriodicity)+Monthly(x.EmailCost,x.EmailPeriodicity)+x.Costs.Sum(c=>Monthly(c.Value,c.Periodicity));
    private static DateOnly? NextDue(ManagedSiteEntity x)=>Renewals(x).Order().Cast<DateOnly?>().FirstOrDefault();
    private static IEnumerable<DateOnly> Renewals(ManagedSiteEntity x){if(x.DomainRenewalOn is{}d)yield return d;if(x.HostingRenewalOn is{}h)yield return h;if(x.EmailRenewalOn is{}e)yield return e;if(x.NextChargeOn is{}c)yield return c;foreach(var cost in x.Costs)if(cost.NextRenewalOn is{}r)yield return r;}
    private static bool IsPending(ManagedSiteEntity x)=>x.FinancialStatus is ManagedSiteFinancialStatus.Pending or ManagedSiteFinancialStatus.Overdue||x.ContractStatus==ManagedSiteContractStatus.AwaitingSignature||x.Status is ManagedSiteStatus.AwaitingMaterials or ManagedSiteStatus.AwaitingApproval;

    private static void Apply(ManagedSiteEntity x,ManagedSiteSaveCommand c,DateTime now)
    {
        x.TradeName=c.TradeName.Trim();x.LegalName=c.LegalName?.Trim();x.Document=BrazilianDocument.Normalize(c.Document);x.ContactName=c.ContactName?.Trim();x.Phone=Digits(c.Phone);x.WhatsApp=Digits(c.WhatsApp);x.Email=c.Email?.Trim();x.Notes=c.Notes?.Trim();x.ProjectName=c.ProjectName.Trim();x.Domain=NormalizeDomain(c.Domain);x.SiteType=c.SiteType?.Trim();x.Scope=c.Scope?.Trim();x.ContractedOn=c.ContractedOn;x.StartedOn=c.StartedOn;x.ExpectedDeliveryOn=c.ExpectedDeliveryOn;x.PublishedOn=c.PublishedOn;x.Status=c.Status;x.ContractedRevisions=c.ContractedRevisions;x.UsedRevisions=c.UsedRevisions;x.Active=c.Active;
        x.DomainRegistrar=c.DomainRegistrar;x.DomainHolder=c.DomainHolder;x.DomainManagedByClient=c.DomainManagedByClient;x.DomainRenewalOn=c.DomainRenewalOn;x.DomainCost=c.DomainCost;x.DomainNotes=c.DomainNotes;x.DnsProvider=c.DnsProvider;x.DnsNotes=c.DnsNotes;x.HostingProvider=c.HostingProvider;x.HostingPlan=c.HostingPlan;x.HostingAdminUrl=c.HostingAdminUrl;x.HostingCost=c.HostingCost;x.HostingPeriodicity=c.HostingPeriodicity;x.HostingRenewalOn=c.HostingRenewalOn;x.HostingStatus=c.HostingStatus;x.DeployPlatform=c.DeployPlatform;x.ProductionUrl=c.ProductionUrl;x.StagingUrl=c.StagingUrl;x.RepositoryUrl=c.RepositoryUrl;x.ProductionBranch=c.ProductionBranch;x.DeployNotes=c.DeployNotes;x.CredentialReference=c.CredentialReference;x.SslStatus=c.SslStatus;x.SslExpiresOn=c.SslExpiresOn;
        x.EmailProvider=c.EmailProvider;x.EmailPlan=c.EmailPlan;x.EmailIncludedCount=c.EmailIncludedCount;x.EmailCost=c.EmailCost;x.EmailPeriodicity=c.EmailPeriodicity;x.EmailRenewalOn=c.EmailRenewalOn;x.EmailStatus=c.EmailStatus;x.DevelopmentContractValue=c.DevelopmentContractValue;x.DevelopmentReceivedValue=c.DevelopmentReceivedValue;x.PaymentMethod=c.PaymentMethod;x.PaymentTerms=c.PaymentTerms;x.DevelopmentPaymentStatus=c.DevelopmentPaymentStatus;x.MonthlyFee=c.MonthlyFee;x.EstimatedRecurringCost=c.EstimatedRecurringCost;x.DueDay=c.DueDay;x.NextChargeOn=c.NextChargeOn;x.FinancialStatus=c.FinancialStatus;x.HasContract=c.HasContract;x.ContractStatus=c.ContractStatus;x.ContractStartOn=c.ContractStartOn;x.ContractSignedOn=c.ContractSignedOn;x.ContractTermMonths=c.ContractTermMonths;x.CancellationNoticeDays=c.CancellationNoticeDays;x.IncludedRevisions=c.IncludedRevisions;x.MonthlySupportHours=c.MonthlySupportHours;x.ContractNotes=c.ContractNotes;x.UpdatedAt=now;
        x.Mailboxes.Clear();x.Mailboxes.AddRange(c.Mailboxes.Select(m=>new ManagedSiteMailboxEntity(x.Id){Address=m.Address.Trim(),OwnerName=m.OwnerName?.Trim(),Type=m.Type,Status=m.Status,Notes=m.Notes?.Trim()}));x.Costs.Clear();x.Costs.AddRange(c.Costs.Select(v=>new ManagedSiteCostEntity(x.Id){Description=v.Description.Trim(),Category=v.Category.Trim(),Supplier=v.Supplier?.Trim(),Value=v.Value,Periodicity=v.Periodicity,NextRenewalOn=v.NextRenewalOn,Notes=v.Notes?.Trim()}));x.SupportEntries.Clear();x.SupportEntries.AddRange(c.SupportEntries.Select(s=>new ManagedSiteSupportEntity(x.Id){OccurredAt=s.OccurredAt,Type=s.Type.Trim(),Description=s.Description.Trim(),HoursSpent=s.HoursSpent,Billable=s.Billable,AdditionalValue=s.AdditionalValue,Status=s.Status?.Trim(),Notes=s.Notes?.Trim()}));
    }
    private static string? Digits(string? value)=>string.IsNullOrWhiteSpace(value)?null:new string(value.Where(char.IsDigit).ToArray());
    private static ManagedSiteDetails Map(ManagedSiteEntity x){var cost=RecurringCost(x);var monthStart=new DateTime(DateTime.UtcNow.Year,DateTime.UtcNow.Month,1);var hours=x.SupportEntries.Where(s=>s.OccurredAt>=monthStart).Sum(s=>s.HoursSpent);var data=new ManagedSiteSaveCommand{TradeName=x.TradeName,LegalName=x.LegalName,Document=x.Document,ContactName=x.ContactName,Phone=x.Phone,WhatsApp=x.WhatsApp,Email=x.Email,Notes=x.Notes,ProjectName=x.ProjectName,Domain=x.Domain,SiteType=x.SiteType,Scope=x.Scope,ContractedOn=x.ContractedOn,StartedOn=x.StartedOn,ExpectedDeliveryOn=x.ExpectedDeliveryOn,PublishedOn=x.PublishedOn,Status=x.Status,ContractedRevisions=x.ContractedRevisions,UsedRevisions=x.UsedRevisions,Active=x.Active,DomainRegistrar=x.DomainRegistrar,DomainHolder=x.DomainHolder,DomainManagedByClient=x.DomainManagedByClient,DomainRenewalOn=x.DomainRenewalOn,DomainCost=x.DomainCost,DomainNotes=x.DomainNotes,DnsProvider=x.DnsProvider,DnsNotes=x.DnsNotes,HostingProvider=x.HostingProvider,HostingPlan=x.HostingPlan,HostingAdminUrl=x.HostingAdminUrl,HostingCost=x.HostingCost,HostingPeriodicity=x.HostingPeriodicity,HostingRenewalOn=x.HostingRenewalOn,HostingStatus=x.HostingStatus,DeployPlatform=x.DeployPlatform,ProductionUrl=x.ProductionUrl,StagingUrl=x.StagingUrl,RepositoryUrl=x.RepositoryUrl,ProductionBranch=x.ProductionBranch,DeployNotes=x.DeployNotes,CredentialReference=x.CredentialReference,SslStatus=x.SslStatus,SslExpiresOn=x.SslExpiresOn,EmailProvider=x.EmailProvider,EmailPlan=x.EmailPlan,EmailIncludedCount=x.EmailIncludedCount,EmailCost=x.EmailCost,EmailPeriodicity=x.EmailPeriodicity,EmailRenewalOn=x.EmailRenewalOn,EmailStatus=x.EmailStatus,DevelopmentContractValue=x.DevelopmentContractValue,DevelopmentReceivedValue=x.DevelopmentReceivedValue,PaymentMethod=x.PaymentMethod,PaymentTerms=x.PaymentTerms,DevelopmentPaymentStatus=x.DevelopmentPaymentStatus,MonthlyFee=x.MonthlyFee,EstimatedRecurringCost=x.EstimatedRecurringCost,DueDay=x.DueDay,NextChargeOn=x.NextChargeOn,FinancialStatus=x.FinancialStatus,HasContract=x.HasContract,ContractStatus=x.ContractStatus,ContractStartOn=x.ContractStartOn,ContractSignedOn=x.ContractSignedOn,ContractTermMonths=x.ContractTermMonths,CancellationNoticeDays=x.CancellationNoticeDays,IncludedRevisions=x.IncludedRevisions,MonthlySupportHours=x.MonthlySupportHours,ContractNotes=x.ContractNotes,Mailboxes=x.Mailboxes.Select(m=>new ManagedSiteMailboxInput(m.Address,m.OwnerName,m.Type,m.Status,m.Notes)).ToArray(),Costs=x.Costs.Select(c=>new ManagedSiteCostInput(c.Description,c.Category,c.Supplier,c.Value,c.Periodicity,c.NextRenewalOn,c.Notes)).ToArray(),SupportEntries=x.SupportEntries.Select(s=>new ManagedSiteSupportInput(s.OccurredAt,s.Type,s.Description,s.HoursSpent,s.Billable,s.AdditionalValue,s.Status,s.Notes)).ToArray()};return new(x.Id,data,x.DevelopmentContractValue-x.DevelopmentReceivedValue,cost,x.MonthlyFee-cost,x.MonthlyFee==0?0:(x.MonthlyFee-cost)/x.MonthlyFee*100,hours,Math.Max(0,x.MonthlySupportHours-hours),x.History.OrderByDescending(h=>h.CreatedAt).Select(h=>new ManagedSiteHistoryItem(h.Id,h.CreatedAt,h.Text,h.ActorId)).ToArray());}
}
